#!/usr/bin/env bash
# Autogenerated test: runs as the remote user inside a container built from each compatibility image with godot-dotnet
# installed with default options (version latest), which brings in the dotnet feature through dependsOn.
set -euo pipefail

# shellcheck source=/dev/null
source dev-container-features-test-lib
# The path is computed from $0 at run time, so shellcheck cannot follow it.
# shellcheck source=/dev/null
source "$(dirname "$0")/headless.sh"

# How long the language server may take to accept a connection after the editor starts.
readonly LSP_TIMEOUT=60
readonly HOME_LOCATIONS=(.local/share/godot .config/godot .cache/godot .cache/fontconfig)
readonly GRAPHICAL_LIBRARIES=(libX11.so.6 libwayland-client.so.0 libGL.so.1 libEGL.so.1 libvulkan.so.1 libasound.so.2
  libpulse.so.0)

work="$(mktemp -d)"
trap 'rm -rf "${work}"' EXIT

# Runs a command as root: directly when already root, else through passwordless sudo.
as_root() {
  if [[ "$(id -u)" == 0 ]]; then
    "$@"
  else
    sudo -n "$@"
  fi
}

# Neither the remote user's nor root's home holds HOME_LOCATIONS, which Godot and fontconfig write. Root's home is not
# readable by a non-root remote user.
no_godot_files_in_homes() {
  local home
  local path
  # A refused sudo would read as "absent" below, so root access is confirmed first.
  as_root true || return 1
  for home in "${HOME}" /root; do
    for path in "${HOME_LOCATIONS[@]}"; do
      if as_root test -e "${home}/${path}"; then
        printf '  found: %s/%s\n' "${home}" "${path}"
        return 1
      fi
    done
  done
}

# Before godot runs at all: its first run writes these locations, so they cannot pass as written by the install.
check "neither the remote user's nor root's home holds any of ${HOME_LOCATIONS[*]}" no_godot_files_in_homes
# The self-contained mode marker would sit beside the executable, in the release directory the link points into.
no_self_contained_marker() {
  local target
  local release
  target="$(readlink "${LINK}")" || return 1
  release="$(dirname "${target}")"
  [[ ! -e "${release}/_sc_" && ! -e "${release}/._sc_" ]]
}
check "the release directory under /opt/godot-dotnet holds neither _sc_ nor ._sc_" no_self_contained_marker
check "no environment variable whose name starts with GODOT is set" bash -c '! compgen -e | grep "^GODOT"'

check "command -v godot prints /usr/local/bin/godot, a link to godot in a directory directly under /opt/godot-dotnet" \
  godot_links_into_release
check "/opt/godot-dotnet holds the marker and exactly one release directory" one_release_directory

# Every file and directory under /opt/godot-dotnet is owned by root and has neither the group nor the other write
# permission.
owned_by_root_and_not_writable() {
  local found
  found="$(find "${INSTALL_ROOT}" \( ! -user root -o -perm /022 \) -print)" || return 1
  if [[ -n "${found}" ]]; then
    printf '  not owned by root, or writable by group or others:\n%s\n' "${found}"
    return 1
  fi
}
check "every file and directory under /opt/godot-dotnet is owned by root and has no group or other write permission" \
  owned_by_root_and_not_writable
# The marker is a regular file, not a link, owned by root with mode 0644.
marker_owned_by_root() {
  [[ -f "${MARKER}" && ! -L "${MARKER}" && "$(stat --format '%U %a' "${MARKER}")" == "root 644" ]]
}
check "the marker is a regular file owned by root with mode 0644" marker_owned_by_root

check "curl is present after the install" command -v curl
# Debian's and Ubuntu's ca-certificates generate the bundle at /etc/ssl/certs/ca-certificates.crt.
check "the CA certificate bundle is present after the install" test -s /etc/ssl/certs/ca-certificates.crt
check "unzip is present after the install" command -v unzip

# None of GRAPHICAL_LIBRARIES appears in the dynamic linker's cache.
no_graphical_libraries() {
  local cache
  local library
  local status=0
  cache="$(ldconfig -p | awk 'NR > 1 { print $1 }')" || return 1
  for library in "${GRAPHICAL_LIBRARIES[@]}"; do
    if grep -Fqx -- "${library}" <<<"${cache}"; then
      printf '  known to the dynamic linker: %s\n' "${library}"
      status=1
    fi
  done
  return "${status}"
}
check "none of ${GRAPHICAL_LIBRARIES[*]} is known to the dynamic linker" no_graphical_libraries

# `dotnet --list-sdks` exits 0 and lists at least one SDK, each line "<version> [<directory>]".
lists_an_sdk() {
  local sdks
  sdks="$(dotnet --list-sdks)" || return 1
  printf '  dotnet --list-sdks:\n%s\n' "${sdks}"
  [[ "${sdks}" =~ ^[0-9]+\.[0-9]+\.[0-9]+ ]]
}
check "dotnet --list-sdks exits 0 and lists at least one SDK" lists_an_sdk

# DOTNET_ROOT is set and names the directory that the dotnet on PATH resolves into, following symbolic links.
dotnet_root_names_dotnet() {
  local resolved
  resolved="$(readlink -f "$(command -v dotnet)")" || return 1
  printf '  DOTNET_ROOT=%s, dotnet resolves to %s\n' "${DOTNET_ROOT-<unset>}" "${resolved}"
  [[ -n "${DOTNET_ROOT-}" && "$(dirname "${resolved}")" == "$(readlink -f "${DOTNET_ROOT}")" ]]
}
check "DOTNET_ROOT is set and names the directory that dotnet on PATH resolves into" dotnet_root_names_dotnet

# `dotnet --list-sdks` lists at least one SDK, and every SDK it lists lies under DOTNET_ROOT.
sdks_under_dotnet_root() {
  local sdks
  local line
  local directory
  sdks="$(dotnet --list-sdks)" || return 1
  if [[ -z "${sdks}" ]]; then
    echo '  dotnet --list-sdks lists no SDK'
    return 1
  fi
  while read -r line; do
    directory="${line##*[}"
    directory="${directory%]}"
    if [[ "$(readlink -f "${directory}")" != "$(readlink -f "${DOTNET_ROOT}")"/* ]]; then
      printf '  %s lies outside DOTNET_ROOT %s\n' "${line}" "${DOTNET_ROOT}"
      return 1
    fi
  done <<<"${sdks}"
}
check "the SDK that dotnet --list-sdks lists lies under DOTNET_ROOT" sdks_under_dotnet_root

# `godot --version` exits 0 and prints a version, ".stable.mono.official.", and a hexadecimal commit hash.
godot_reports_official_stable_dotnet() {
  local output
  output="$(godot --version)" || return 1
  printf "  got '%s'\n" "${output}"
  [[ "${output}" =~ ^[0-9]+(\.[0-9]+)+\.stable\.mono\.official\.[0-9a-f]+$ ]]
}
check "godot --version exits 0 and prints a version ending in .stable.mono.official. followed by a commit hash" \
  godot_reports_official_stable_dotnet

# Computed at run time: the default option installs whatever release the latest-release link names; a release
# published between build and test fails the comparison once.
latest_tag="$(latest_release_tag)"
printf 'the latest-release link names %s\n' "${latest_tag}"
check "godot --version reports the release that the latest-release link points to" \
  godot_reports_version "${latest_tag%-stable}"

project="${work}/project"
make_project "${project}"
check "godot --headless --path <project> --quit on a minimal project exits 0" \
  godot --headless --path "${project}" --quit

# `godot --headless --path $1 --import` exits 0; its combined output goes to ${work}/import.log and is shown when the
# run fails.
imports_project_headless() {
  if ! godot --headless --path "$1" --import </dev/null >"${work}/import.log" 2>&1; then
    tail -n 20 "${work}/import.log"
    return 1
  fi
}
check "godot --headless --path <project> --import on a minimal project exits 0" imports_project_headless "${project}"

# The import's output holds neither line the editor prints when the font configuration library is missing.
no_missing_fontconfig_reported() {
  if grep -i -E 'libfontconfig\.so\.1: cannot open|unable to load fontconfig' "${work}/import.log"; then return 1; fi
}
check "the import's output reports no missing font configuration library" no_missing_fontconfig_reported
check "the project's .godot/ directory exists after the import" test -d "${project}/.godot"

# Starts `godot --headless --editor --path $1 --lsp-port <port>` in the background on a random port that accepted no
# connection before, and succeeds when a TCP connection to 127.0.0.1:<port> succeeds while the editor runs, within
# LSP_TIMEOUT seconds. The editor is then stopped and reaped; its output is shown when the check fails. The port stays
# below 32768, where Linux's default ephemeral range starts: a probe of an unbound port in that range can connect to
# itself and pass.
serves_language_server() {
  local port=$(( 20000 + RANDOM % 12000 ))
  local pid
  local waited=0
  local status=1
  if (exec 3<>"/dev/tcp/127.0.0.1/${port}") 2>/dev/null; then
    printf '  port %s already accepts connections\n' "${port}"
    return 1
  fi
  godot --headless --editor --path "$1" --lsp-port "${port}" </dev/null >"${work}/lsp.log" 2>&1 &
  pid=$!
  while (( waited < LSP_TIMEOUT )) && kill -0 "${pid}" 2>/dev/null; do
    if (exec 3<>"/dev/tcp/127.0.0.1/${port}") 2>/dev/null; then
      status=0
      break
    fi
    sleep 1
    waited=$(( waited + 1 ))
  done
  if (( status == 0 )); then
    printf '  127.0.0.1:%s accepted a connection after about %s s\n' "${port}" "${waited}"
  else
    printf '  127.0.0.1:%s accepted no connection within %s s\n' "${port}" "${waited}"
  fi
  # Stopped with SIGTERM, then SIGKILL after 10 seconds, so a hanging editor cannot hold the test.
  kill "${pid}" 2>/dev/null || true
  for (( waited = 0; waited < 10; waited++ )); do
    if ! kill -0 "${pid}" 2>/dev/null; then break; fi
    sleep 1
  done
  kill -KILL "${pid}" 2>/dev/null || true
  wait "${pid}" || true
  if (( status != 0 )); then tail -n 20 "${work}/lsp.log"; fi
  return "${status}"
}
check "godot --headless --editor --path <project> --lsp-port <port> accepts TCP connections on 127.0.0.1:<port>" \
  serves_language_server "${project}"

# The C# project restores Godot.NET.Sdk and Godot's packages from nuget.org on its first build.
csharp="${work}/csharp"
check "a minimal C# project for the installed release can be written" make_csharp_project "${csharp}"
check "godot --headless --path <project> --build-solutions --quit on a minimal C# project exits 0 and builds it" \
  builds_csharp_project "${csharp}" "${work}/build.log"
check "godot --headless --path <project> --quit-after <frames> then prints the line of the C# script" \
  runs_csharp_project "${csharp}" "${work}/run.log"

# No file under apt's package lists, which only root can read in full.
package_lists_empty() {
  local files
  files="$(as_root find /var/lib/apt/lists -type f)" || return 1
  if [[ -n "${files}" ]]; then
    printf '  files remain under /var/lib/apt/lists:\n%s\n' "${files}"
    return 1
  fi
}
check "apt's package lists hold no file" package_lists_empty
check "no temporary directory, temporary link, or other release directory of the install remains" no_install_residue

reportResults
